INSERT INTO audit_events VALUES(16054,'2026-08-27 17:08:16','bb5c5549-3bc','builder','/home/iconbaypark2900/dataScience/agpack','','replace_in_file','proposed','','','{"new": "#: Maximum number of entries any bounded list param may carry (origins, fields).\\nMAX_PARAM_LIST_ITEMS = 16\\n\\n#: The prefix (\u00a75.1 spelling) every on-disk scope name carries.\\n_PREFIX = \"agpack/\"\\n\\n#: The grammar for the part after the prefix: ``<area>.<verb>`` (lower-case,\\n#: dot-separated, no wildcards).  This is a *namespace* rule, not a regex\\n#: grant \u2014 the closed :class:`Scope` set below is the *only* thing that matches.\\n_NAME_RE = re.compile(r\"^[a-z][a-z0-9]*(\\.[a-z][a-z0-9]*)*$\")", "old": "#: Maximum number of entries any bounded list param may carry (origins, fields).\\nMAX_PARAM_LIST_ITEMS = 16\\n\\n#: A bare (dotless) scope name is only ever ``random``; everything else is\\n#: ``<area>.<verb>``.  The regex below is the *grammar*; the closed :class:`Scope`\\n#: set below is the *only* thing that matches.  (A namespace rule, not a regex\\n#: grant \u2014 \u00a75.)\\n_NAME_RE = re.compile(r\"^[a-z][a-z0-9]*(\\.[a-z][a-z0-9]*)*$\")\\n_ALLOWED_BARE = frozenset({\"random\"})", "path": "src/agpack/sandbox/capabilities.py"}','','','');
