INSERT INTO audit_events VALUES(19692,'2026-08-28 18:28:04','2ba12f01-eb4','builder','/home/iconbaypark2900/dataScience/agpack','','replace_in_file','proposed','','','{"new": "    The on-disk ``artifact.schema.SignatureBlock`` stores the same fields\\n    as base64 *strings*; this module works in *raw bytes* and converts to\\n    and from that on-disk shape only where a caller needs to (see the\\n    packager), so that no caller can accidentally sign over or verify\\n    against a different byte stream than the manifest was built from.", "old": "    The on-disk ``artifact.schema.SignatureBlock`` stores the same fields\\n    as base64 *strings*; this module works in *raw bytes* and provides\\n    :func:`from_packaged` / :func:`to_packaged` to convert between the two\\n    shapes so that no caller can accidentally sign over or verify against\\n    a different byte stream than the manifest was built from.", "path": "src/agpack/trust/signing.py"}','','','');
