INSERT INTO audit_events VALUES(19776,'2026-08-28 18:35:46','2ba12f01-eb4','builder','/home/iconbaypark2900/dataScience/agpack','','replace_in_file','proposed','','','{"new": "def _scope_in_closed_set(scope: Scope) -> None:\\n    \"\"\"\u00a72: ``scope`` is one of the closed :class:`Scope` set (no leniency).\\n\\n    ``Scope`` is a ``str``-backed :class:`enum.Enum`, so a *bare* string is\\n    indistinguishable from a member by :func:`isinstance`; but a string is\\n    never a member, so ``not isinstance(scope, Scope)`` rejects exactly the\\n    raw strings and non-Scope values we must refuse (and never coerces).\\n    \"\"\"\\n\\n    if not isinstance(scope, Scope):\\n        raise De...", "old": "def _scope_in_closed_set(scope: Scope) -> None:\\n    \"\"\"\u00a72: ``scope`` is one of the closed :class:`Scope` set (no leniency).\"\"\"\\n\\n    if isinstance(scope, str):\\n        # a raw string is not a Scope enum member \u2014 reject it, don''t coerce\\n        raise DelegationViolation(f\"scope {scope!r} is not a closed Scope value\")\\n    if not isinstance(scope, Scope):\\n        raise DelegationViolation(f\"scope must be a Scope, got {type(scope).__name__}\")", "path": "src/agpack/trust/delegation.py"}','','','');
