INSERT INTO audit_events VALUES(21208,'2026-08-28 21:54:40','1d5e5635-ce5','builder','/home/iconbaypark2900/dataScience/agpack','','replace_in_file','proposed','','','{"old": "def test_hop_signature_wrong_key_rejected() -> None:\\n    # sub hop signed by sub; if the registry only has root''s key, reject\\n    keys = {\"acme/copywriter\": _ROOT_PUB}\\n    assert_violation(\\n        lambda: verify(_valid_token(), logical_now_unix=_NOW, keys=keys),\\n        \"does not verify\",\\n    )", "new": "def test_hop_signature_wrong_key_rejected() -> None:\\n    # sub hop is signed by _SUB, but the registry maps the sub agent to the\\n    # *root* public key. The root hop still verifies (its real key), so verify\\n    # proceeds to the sub hop and rejects it for a bad signature.\\n    keys = {\\n        \"acme/orch\": _ROOT_PUB,\\n        \"acme/copywriter\": _ROOT_PUB,  # wrong key for the sub agent\\n    }\\n    assert_violation(\\n        lambda: verify(_valid_token(), logical_now_unix=_NOW, keys=keys)...", "path": "tests/test_trust_delegation.py", "expected_replacements": 1}','','','');
